// Package example holds sorters generated by blqsortgen. Its tests check
// that they compile side by side in one package and sort correctly.
package example

//go:generate go run github.com/dlm/blqsort/cmd/blqsortgen -type Person -by=-Age,Name.Last,Name.First
//go:generate go run github.com/dlm/blqsort/cmd/blqsortgen -type Person -by Score -func sortPeopleByScore
//go:generate go run github.com/dlm/blqsort/cmd/blqsortgen -type *Person -by ID -func sortPersonPointers

type Name struct {
	First, Last string
}

type Person struct {
	ID    int64
	Name  Name
	Age   int
	Score float64
}
